const char *dfAidName(u32 aid, const char **vendor)
{
	int lo = 0, hi = sizeof(names) / sizeof(names[0]) - 1;
	while (lo <= hi) {
		int m = (lo + hi) / 2;
		if (names[m].aid == aid) {
			if (vendor) *vendor = names[m].vendor;
			return names[m].name;
		}
		if (names[m].aid < aid) lo = m + 1;
		else hi = m - 1;
	}
	return NULL;
}
